import { test, expect } from '@playwright/test';

test.describe('User Profile - Active Sessions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
    await page.fill('input[name="username"]', 'testuser');
    await page.fill('input[name="password"]', 'password123');
    await page.click('button[type="submit"]');
  });

  test('should display all active sessions', async ({ page }) => {
    const sessionsList = await page.getByRole('list', { name: 'Active Sessions' });
    await expect(sessionsList).toBeVisible();
    const sessionItems = await sessionsList.locator('li');
    await expect(sessionItems).toHaveCount(3); // Assuming there are 3 active sessions
  });

  test('should log out of a specific session', async ({ page }) => {
    const sessionToLogout = await page.getByText('Session from Device XYZ');
    await expect(sessionToLogout).toBeVisible();
    await sessionToLogout.locator('button', { name: 'Log Out' }).click();
    await expect(sessionToLogout).not.toBeVisible();
  });
});
